#' Venn_Comparison_DryR
#'
#' @description A function to compare a list of genes to the DryR list of genes.
#' 
#' @param dryList An object with the models generated by DryR.
#' @param FilterGenesTable A table with all the genes. It must have a column named "gene_id" with rows being ENSEMBL name codes for each gene.
#' 
#' @return A Venn diagram showing numbers and percentages of shared and exclusive genes between the user's dataset and the DryR publicly available dataset.
#' @export

Venn_Comparison_DryR <- function(dryList, FilterGenesTable) {
  # Prepare data
  ## From DryR dataset
  DryR_WT_dataset_1 <- readxl::read_excel("./data/DryR_WT_dataset.xlsx", sheet = "S1_1")
  DryR_WT_dataset_2 <- readxl::read_excel("./data/DryR_WT_dataset.xlsx", sheet = "S1_2")
  
  colnames(DryR_WT_dataset_1) <- DryR_WT_dataset_1[1, ]
  DryR_WT_dataset_1 <- DryR_WT_dataset_1[-1, ]
  
  colnames(DryR_WT_dataset_2) <- DryR_WT_dataset_2[1, ]
  DryR_WT_dataset_2 <- DryR_WT_dataset_2[-1, ]
  
  DryR_WT_genes_1 <- DryR_WT_dataset_1$`gene ID`
  DryR_WT_genes_2 <- DryR_WT_dataset_2$`gene identifier`
  
  ## Filtered genes from our dataset
  filtered_genes <- paste0(FilterGenesTable$gene_id, "|", FilterGenesTable$gene_name)
  
  ## List of all detected genes
  common_genes <- list(filtered_genes, DryR_WT_dataset_1$`gene ID`)
  common_genes <- do.call(intersect, common_genes)
  
  # Venn plots
  ## All detected genes
  ggvenn::ggvenn(
    list(
      filtered_genes = filtered_genes,
      DryR_Bmal_WT_AL_rythmic = DryR_WT_genes_1,
      DryR_CRY_WT_AL_rythmic = DryR_WT_genes_2
    )
  )
  
  ## Rhythmic genes
  venn_list <- list(
    filtered_genes = filtered_genes[filtered_genes %in% common_genes &
                                      !is.na(dryList$parameters$phase_CTRL)],
    DryR_Bmal_WT_AL_rythmic = DryR_WT_genes_1[DryR_WT_dataset_1$phase_Bmal1_WT_AL != "NA"],
    DryR_CRY_WT_AL_rythmic = DryR_WT_genes_2[DryR_WT_dataset_2$phase_CRY_WT_AL != "NA"]
  )
  ggvenn::ggvenn(venn_list, set_name_size = 3, text_size = 3)
}
